console.log('Has trailing newline:', secretKey.endsWith('\n'));
console.log('Has trailing space:', secretKey.endsWith(' '));
console.log('Last 3 char codes:', JSON.stringify([...secretKey.slice(-3)].map(c => c.charCodeAt(0))));
console.log('REGION:', region);

if (!accessKey || !secretKey) {
  console.error('FATAL: AWS credentials missing');
  process.exit(1);
}

// Set env vars (trimmed) and run the upload script
