console.log('\n=== Running upload script ===');
const child = execSync(`node "${uploadScript}" "${apkPath}" "${s3Key}"`, {
  env,
  encoding: 'utf-8',
  stdio: 'pipe',
  timeout: 300000,
});
console.log(child);
