}

const accessKey = fetchEnvVar('AWS_ACCESS_KEY_ID');
const secretKey = fetchEnvVar('AWS_SECRET_ACCESS_KEY');
const region = fetchEnvVar('AWS_REGION') || 'us-east-1';

console.log('ACCESS_KEY_ID:', accessKey.substring(0, 4) + '...' + accessKey.slice(-4), 'len:', accessKey.length);
console.log('SECRET_ACCESS_KEY len:', secretKey.length);
