  const resp = execSync(`curl -sS -m 15 -w "\\nHTTP_STATUS:%{http_code}" -H "Authorization: ${authHeader}" -H "x-amz-content-sha256: ${payloadHash}" -H "x-amz-date: ${amzDate}" "${url}"`, { encoding: 'utf-8' });
